switch (order.status) {
  case 'CART':
  case 'PAYMENT_FAILED':
    // 課金されていないので、返金せずにそのまま取り消す
    order.status = 'CANCELLED';
    break;
  case 'PAID': {
    // 今のまま（返金 → CANCELLED → break）
  }
  // PENDING_PAYMENT は課金されたか分からない。照合バッチが
  // PAID か PAYMENT_FAILED に決めるまで、キャンセルを受け付けない
  default:
    throw new InvalidOrderStateError(order, 'cancelled');
}

const raw = env.CANCELLATION_FEE_PERCENT ?? '10';
const feePercent = Number(raw);
if (!Number.isInteger(feePercent) || feePercent < 0 || feePercent > 100) {
  throw new Error(`CANCELLATION_FEE_PERCENT must be 0-100: ${raw}`);
}
